import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.E2BN9oyn.js";const g=JSON.parse('{"title":"Curated workouts are locked catalog items at three levels","description":"","frontmatter":{"status":"accepted","date":"2026-11-22T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0034-curated-workouts-are-locked-catalog-items-at-three-levels.md","filePath":"docs/adr/0034-curated-workouts-are-locked-catalog-items-at-three-levels.md"}'),r={name:"docs/adr/0034-curated-workouts-are-locked-catalog-items-at-three-levels.md"};function i(n,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="curated-workouts-are-locked-catalog-items-at-three-levels" tabindex="-1">Curated workouts are locked catalog items at three levels <a class="header-anchor" href="#curated-workouts-are-locked-catalog-items-at-three-levels" aria-label="Permalink to &quot;Curated workouts are locked catalog items at three levels&quot;">​</a></h1><p>The catalog held only exercises (<a href="./0033-the-server-database-is-the-catalog-and-nothing-ships-bundled">ADR 0033</a>). It also offers <strong>curated workouts</strong>: ready-made workouts at different levels. The shape was set by looking at how a personalised training app organises its sessions, without borrowing its names or content, and decided by the maintainer.</p><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><ul><li><strong>A curated workout is a catalog item</strong>, held in the server database beside the exercises. The admin writes, publishes and retires it, and it has a slug that never changes and numbered revisions (<a href="./0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a>). Phones download it item by item, without an account, and it is always available, like an exercise.</li><li><strong>It is locked.</strong> A person starts it as it is. Editing it makes a copy in their library, a normal workout that no longer follows the catalog. Later revisions never change a copy.</li><li><strong>There are three fixed levels</strong>, the same for every goal, named starter, steady and strong until the brand pages settle the words. A person picks the level; nothing suggests one.</li><li><strong>One workout per level.</strong> The same workout at three levels is three curated workouts, grouped in a workout family, so each level can change its exercises, reps, rests and rounds freely. Swapping exercises by level would need new engine logic and is not done.</li><li><strong>The first version is a browsable list by level.</strong> The admin writes about ten families to start.</li></ul><h2 id="left-out-of-the-first-version" tabindex="-1">Left out of the first version <a class="header-anchor" href="#left-out-of-the-first-version" aria-label="Permalink to &quot;Left out of the first version&quot;">​</a></h2><p>Suggesting a level from a questionnaire, an effort rating after a session, filters by time or equipment, and curated plans (training plans, <a href="https://github.com/tkint/coach-poulpy/issues/17" target="_blank" rel="noreferrer">#17</a>, come first). Each is its own decision later.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The catalog&#39;s revision, retire and offer-again rules apply to curated workouts unchanged. A retired curated workout stays so copies and sessions still open.</li><li>A curated workout uses exercises by slug. Retiring an exercise a curated workout uses needs the admin to see the workouts it affects.</li><li>The library holds only what a person made, copied or was shared; catalog items are not in it.</li><li>Locked workouts mean a person never loses a curated workout by editing it, and the catalog can fix one for everyone.</li></ul>',8)])])}const f=t(r,[["render",i]]);export{g as __pageData,f as default};
